CREATE DATABASE IF NOT EXISTS csat_nps CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE csat_nps;
CREATE TABLE IF NOT EXISTS Customer (CustomerID INT AUTO_INCREMENT PRIMARY KEY,FullName VARCHAR(100) NOT NULL,Phone VARCHAR(20),Email VARCHAR(100));
CREATE TABLE IF NOT EXISTS Store (StoreID INT AUTO_INCREMENT PRIMARY KEY,StoreName VARCHAR(100) NOT NULL,Address VARCHAR(255));
CREATE TABLE IF NOT EXISTS WarrantyTicket (TicketID INT AUTO_INCREMENT PRIMARY KEY,CustomerID INT NOT NULL,StoreID INT NOT NULL,CompletedDate DATE,Status VARCHAR(50),FOREIGN KEY(CustomerID) REFERENCES Customer(CustomerID),FOREIGN KEY(StoreID) REFERENCES Store(StoreID));
CREATE TABLE IF NOT EXISTS Survey (SurveyID INT AUTO_INCREMENT PRIMARY KEY,TicketID INT NOT NULL UNIQUE,SentDate DATE NOT NULL,ExpireDate DATE NOT NULL,FOREIGN KEY(TicketID) REFERENCES WarrantyTicket(TicketID));
CREATE TABLE IF NOT EXISTS Feedback (FeedbackID INT AUTO_INCREMENT PRIMARY KEY,SurveyID INT NOT NULL,CSATScore INT NOT NULL,NPSScore INT NOT NULL,Comment TEXT,SubmittedDate DATE NOT NULL,CONSTRAINT chk_csat CHECK (CSATScore BETWEEN 1 AND 5),CONSTRAINT chk_nps CHECK (NPSScore BETWEEN 0 AND 10),FOREIGN KEY(SurveyID) REFERENCES Survey(SurveyID) ON DELETE CASCADE);
